    /// Run retention cleanup and log the maintenance event
    pub async fn retention_cleanup(&self, before_ts: i64) -> Result<usize> {
        let deleted = self.prune_segments_before(before_ts).await?;
        let metadata = serde_json::json!({
            "deleted_segments": deleted,
            "before_ts": before_ts,
        })
        .to_string();
        let record = MaintenanceRecord {
            id: 0,
            event_type: "retention_cleanup".to_string(),
            message: Some(format!("Deleted {deleted} output segments")),
            metadata: Some(metadata),
            timestamp: now_ms(),
        };
        let _ = self.record_maintenance(record).await?;
        Ok(deleted)
    }

    /// ft-xbnl0.2.3 Cx-first sibling of [`retention_cleanup`].
    ///
    /// Routes both the prune and the maintenance-log write through their
    /// cx-first siblings so the full composite honours cancellation.
    pub async fn retention_cleanup_with_cx(
        &self,
        cx: &crate::cx::Cx,
        before_ts: i64,
    ) -> Result<usize> {
        Self::checkpoint_storage_operation(cx, "retention_cleanup")?;
        let deleted = self.prune_segments_before_with_cx(cx, before_ts).await?;
        let metadata = serde_json::json!({
            "deleted_segments": deleted,
            "before_ts": before_ts,
        })
        .to_string();
        let record = MaintenanceRecord {
            id: 0,
            event_type: "retention_cleanup".to_string(),
            message: Some(format!("Deleted {deleted} output segments")),
            metadata: Some(metadata),
            timestamp: now_ms(),
        };
        let _ = self.record_maintenance_with_cx(cx, record).await?;
        Ok(deleted)
    }

    /// Enforce the configured size-based retention cap
    /// (`storage.retention_max_mb`) by evicting the oldest output segments
    /// until the live database size is under the limit.
    ///
    /// "Live size" is `(page_count - free_pages) * page_size` — the non-free
    /// pages actually holding data. Bounding it bounds unbounded growth even
    /// without a `VACUUM`, because SQLite recycles freelist pages for
    /// subsequent inserts, so the file plateaus rather than growing forever.
    ///
    /// `max_mb == 0` disables the cap and is a no-op. Returns a
    /// [`SizeEvictionOutcome`] describing what was evicted.
    pub async fn enforce_size_limit(&self, max_mb: u32) -> Result<SizeEvictionOutcome> {
        let cx = crate::cx::Cx::current().unwrap_or_else(crate::cx::for_request);
        self.enforce_size_limit_with_cx(&cx, max_mb).await
    }

    /// Cx-first sibling of [`enforce_size_limit`].
    pub async fn enforce_size_limit_with_cx(
        &self,
        cx: &crate::cx::Cx,
        max_mb: u32,
    ) -> Result<SizeEvictionOutcome> {
        Self::checkpoint_storage_operation(cx, "enforce_size_limit")?;
        let (tx, rx) = oneshot::channel();
        self.write_tx
            .send_with_cx(
                cx,
                WriteCommand::EnforceSizeLimit {
                    max_mb,
                    respond: tx,
                },
            )
            .await
            .map_err(|error| Self::writer_send_error("enforce_size_limit", error))?;
        Self::recv_writer_response(rx).await
    }

