#[test]
fn hybrid_backend_search_returns_fused_ranked_results() {
    let backend = memory_backend();

    let now_ms = 1_700_000_000_000i64;
    seed_pane_backend(&backend, 1, now_ms);

    let content_a = "hybrid needle alpha";
    let seg_a = seed_segment_backend(&backend, 1, 0, content_a, now_ms);

    let content_b = "hybrid needle beta";
    let seg_b = seed_segment_backend(&backend, 1, 1, content_b, now_ms + 1);

    let query_vector = [1.0_f32, 0.0];
    let vector_a = encode_f32_embedding_blob(&[1.0_f32, 0.0]).unwrap();
    let vector_b = encode_f32_embedding_blob(&[0.0_f32, 1.0]).unwrap();
    seed_segment_embedding_backend(&backend, seg_a, "hybrid-embedder", 2, &vector_a, now_ms);
    seed_segment_embedding_backend(&backend, seg_b, "hybrid-embedder", 2, &vector_b, now_ms + 1);

    let options = SearchOptions {
        limit: Some(2),
        ..SearchOptions::default()
    };
    let backend_state = Arc::new(Mutex::new(SemanticBudgetState::new(
        SemanticBudgetConfig::default(),
    )));
    let via_backend = hybrid_search_with_results_backend(
        &backend,
        "needle",
        &options,
        "hybrid-embedder",
        &query_vector,
        SearchMode::Hybrid,
        60,
        0.5,
        0.5,
        Some(FusionBackend::FrankenSearchRrf),
        &backend_state,
    ).unwrap();

    assert_eq!(via_backend.mode, "hybrid");
    assert_eq!(via_backend.requested_mode, "hybrid");
    assert_eq!(via_backend.fallback_reason, None);
    assert_eq!(via_backend.lexical_candidates, 2);
    assert_eq!(via_backend.semantic_candidates, 2);
    assert_eq!(via_backend.semantic_rows_scanned, 2);
    assert_eq!(via_backend.semantic_budget_state, "active");
    assert_eq!(via_backend.results.len(), 2);

    let first = &via_backend.results[0];
    let second = &via_backend.results[1];
    assert_eq!(first.result.segment.id, seg_a);
    assert_eq!(first.result.segment.content, content_a);
    assert_eq!(first.lexical_rank, Some(0));
    assert_eq!(first.semantic_rank, Some(0));
    assert_eq!(first.fusion_rank, 0);
    assert_eq!(first.semantic_score, Some(1.0));
    assert!(first.lexical_contribution.is_some());
    assert!(first.semantic_contribution.is_some());

    assert_eq!(second.result.segment.id, seg_b);
    assert_eq!(second.result.segment.content, content_b);
    assert_eq!(second.lexical_rank, Some(1));
    assert_eq!(second.semantic_rank, Some(1));
    assert_eq!(second.fusion_rank, 1);
    assert_eq!(second.semantic_score, Some(0.0));
    assert!(second.lexical_contribution.is_some());
    assert!(second.semantic_contribution.is_some());
    assert!(
        first.fusion_score > second.fusion_score,
        "matching lexical+semantic rank should outrank the weaker candidate"
    );
}

