// =========================================================================
// wa-4vx.3.7: Async StorageHandle Tests
// =========================================================================

// [ft-upvjr / ft-3tvvt] The lighter-weight `run_async_test` was removed
// — every `#[test]` in `storage.rs` and the four sibling test files
// (storage_handle_tests, queue_depth_tests, backpressure_integration_tests,
// timeline_integration_tests) now routes through the panic-catching +
// runtime-drop-absorbing `run_storage_async_test` below. Centralizing on
// the robust helper means a TLS destructor panic during runtime drop no
// longer leaks across `#[test]` boundaries on asupersync.

#[cfg(test)]
pub(super) fn run_storage_async_test<F>(future: F)
where
    F: std::future::Future<Output = ()>,
{
    use crate::runtime_async::CompatRuntime;
    let runtime = crate::runtime_async::RuntimeBuilder::current_thread()
        .enable_all()
        .build()
        .expect("failed to build storage test runtime");
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        runtime.block_on(future);
    }));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        drop(runtime);
    }));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        crate::runtime_async::clear_runtime_handle();
    }));
    if let Err(payload) = result {
        std::panic::resume_unwind(payload);
    }
}

/// [ft-iq339 / ft-3tvvt] Multi-thread sibling of
/// [`run_storage_async_test`] for proptest cases that need the
/// multi-thread runtime (writer + reader concurrency under
/// proptest-driven load). Same panic-catching + runtime-drop-absorbing
/// envelope, but the body returns the future's value so the proptest
/// can `prop_assert_*` on the verification results outside the
/// async block. Replaces the ad-hoc `RuntimeBuilder::multi_thread()
/// .build().expect(...).block_on(...)` boilerplate in
/// `storage::proptest_tests`.
#[cfg(test)]
pub(super) fn run_storage_proptest_async<F, T>(future: F) -> T
where
    F: std::future::Future<Output = T>,
{
    use crate::runtime_async::CompatRuntime;
    let runtime = crate::runtime_async::RuntimeBuilder::multi_thread()
        .build()
        .expect("failed to build storage proptest runtime");
    let result =
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| runtime.block_on(future)));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        drop(runtime);
    }));
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        crate::runtime_async::clear_runtime_handle();
    }));
    match result {
        Ok(value) => value,
        Err(payload) => std::panic::resume_unwind(payload),
    }
}

/// ft-xbnl0.2.3 Cx-first: `StorageHandle::new_with_cx` must
/// open the DB identically to `new` when given a fresh cx —
/// producing a handle that supports the same upsert/shutdown
/// lifecycle as the legacy path.
#[test]
fn storage_handle_new_with_cx_succeeds_on_fresh_cx() {
    run_storage_async_test(async {
        let temp_dir = std::env::temp_dir();
        let db_path = temp_dir.join(format!("wa_test_new_with_cx_{}.db", std::process::id()));
        let db_path_str = db_path.to_string_lossy().to_string();

        let cx = crate::cx::for_testing();
        let storage = StorageHandle::new_with_cx(&cx, &db_path_str).await.unwrap();

        let pane = PaneRecord {
            pane_id: 7,
            pane_uuid: None,
            domain: "local".to_string(),
            window_id: None,
            tab_id: None,
            title: Some("cx-first".to_string()),
            cwd: None,
            tty_name: None,
            first_seen_at: 1_700_000_000_000,
            last_seen_at: 1_700_000_000_000,
            observed: true,
            ignore_reason: None,
            last_decision_at: None,
        };
        storage.upsert_pane(pane).await.unwrap();
        storage.shutdown().await.unwrap();

        let _ = std::fs::remove_file(&db_path);
        let _ = std::fs::remove_file(format!("{db_path_str}-wal"));
        let _ = std::fs::remove_file(format!("{db_path_str}-shm"));
    });
}

/// ft-nveha: a custom `[storage] writer_queue_size` must actually reach the
/// constructed `StorageHandle`. Previously the parsed value was dropped (no
/// canonical conversion) and the writer channel used the default capacity.
/// Asserts both the `From` mapping and the live handle's write-queue capacity.
#[test]
fn storage_writer_queue_size_reaches_handle() {
    // Pure mapping: the From conversion carries writer_queue_size -> write_queue_size.
    let app = crate::config::StorageConfig {
        writer_queue_size: 7,
        ..crate::config::StorageConfig::default()
    };
    assert_eq!(
        StorageConfig::from(&app).write_queue_size,
        7,
        "From must carry the parsed writer_queue_size through"
    );

    // End-to-end: the value reaches the live handle's write-queue capacity.
    run_storage_async_test(async {
        let temp_dir = std::env::temp_dir();
        let db_path = temp_dir.join(format!("wa_test_nveha_qsize_{}.db", std::process::id()));
        let db_path_str = db_path.to_string_lossy().to_string();

        let cx = crate::cx::for_testing();
        let app = crate::config::StorageConfig {
            writer_queue_size: 7,
            ..crate::config::StorageConfig::default()
        };
        let storage =
            StorageHandle::with_config_with_cx(&cx, &db_path_str, StorageConfig::from(&app))
                .await
                .unwrap();
        assert_eq!(
            storage.write_queue_capacity(),
            7,
            "parsed [storage] writer_queue_size=7 must reach the handle's write-queue capacity (was: default)"
        );
        storage.shutdown().await.unwrap();

        let _ = std::fs::remove_file(&db_path);
        let _ = std::fs::remove_file(format!("{db_path_str}-wal"));
        let _ = std::fs::remove_file(format!("{db_path_str}-shm"));
    });
}

/// ft-rrqhm: `storage.retention_max_mb` must actually enforce a size cap.
/// Before this fix the value was parsed into config but no size-based eviction
/// existed, so the database grew unbounded. This drives the real writer-thread
/// `enforce_size_limit` path end-to-end: append data well past a 1 MiB cap,
/// enforce it, and assert the oldest segments are evicted and the live size
/// shrinks — while `max_mb == 0` and an over-cap value stay no-ops.
#[test]
fn enforce_size_limit_evicts_oldest_segments_under_cap() {
    run_storage_async_test(async {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let db_path = temp_dir.path().join("ft_rrqhm_size_cap.db");
        let db_path_str = db_path.to_string_lossy().to_string();

        let cx = crate::cx::for_testing();
        let storage =
            StorageHandle::with_config_with_cx(&cx, &db_path_str, StorageConfig::default())
                .await
                .unwrap();

        // Segments carry a foreign key to their pane row; register the pane
        // before appending (matches the live capture path).
        storage
            .upsert_pane(PaneRecord {
                pane_id: 7,
                pane_uuid: None,
                domain: "local".to_string(),
                window_id: None,
                tab_id: None,
                title: Some("size-cap".to_string()),
                cwd: None,
                tty_name: None,
                first_seen_at: 1_700_000_000_000,
                last_seen_at: 1_700_000_000_000,
                observed: true,
                ignore_reason: None,
                last_decision_at: None,
            })
            .await
            .unwrap();

        // Low-cardinality content (a single repeated char) keeps the FTS index
        // tiny so the output_segments content dominates the live size, making
        // the byte accounting deterministic. 256 x 16 KiB ~= 4 MiB of content.
        let big = "x".repeat(16 * 1024);
        for i in 0..256u64 {
            storage
                .append_segment(7, &format!("seg-{i}-{big}"), None)
                .await
                .unwrap();
        }
        // Move the WAL into the main file so PRAGMA page_count is stable.
        storage.checkpoint().await.unwrap();

        let total_before = storage.count_segments_before(i64::MAX).await.unwrap();
        assert_eq!(total_before, 256, "all appended segments should be present");

        // max_mb == 0 disables the cap: a no-op even when the DB is large.
        let disabled = storage.enforce_size_limit(0).await.unwrap();
        assert_eq!(disabled.deleted_segments, 0, "cap=0 must be a no-op");
        assert_eq!(
            storage.count_segments_before(i64::MAX).await.unwrap(),
            256,
            "cap=0 must not delete anything"
        );

        // Enforce a 1 MiB cap: must evict the oldest segments and shrink size.
        let outcome = storage.enforce_size_limit(1).await.unwrap();
        assert!(
            outcome.deleted_segments > 0,
            "expected size eviction, got {outcome:?}"
        );
        assert!(
            outcome.used_bytes_after < outcome.used_bytes_before,
            "live database size must shrink after eviction: {outcome:?}"
        );

        // Eviction is partial (some newest segments survive) and oldest-first.
        let remaining = storage.count_segments_before(i64::MAX).await.unwrap();
        assert!(
            remaining > 0 && remaining < 256,
            "expected partial oldest-first eviction, {remaining} remain"
        );
        let recent = storage.get_segments(7, 1).await.unwrap();
        assert!(
            !recent.is_empty(),
            "the newest segment must survive size eviction"
        );

        // A pass with a cap above the current size is a no-op.
        let noop = storage.enforce_size_limit(4096).await.unwrap();
        assert_eq!(
            noop.deleted_segments, 0,
            "an under-cap enforcement must not evict, got {noop:?}"
        );

        storage.shutdown().await.unwrap();
    });
}

/// ft-y76wt: a custom `[storage] read_pool_size` must actually reach the
/// constructed `StorageHandle` and its default rusqlite backend provider.
/// Previously the parsed value had no consumer — the read
/// pool always retained the compiled-in `DEFAULT_READ_POOL_MAX_PER_PATH`.
/// Asserts both the `From` mapping and the live handle's read-pool capacity.
#[test]
fn storage_read_pool_size_reaches_handle() {
    // Pure mapping: the From conversion carries read_pool_size through.
    let app = crate::config::StorageConfig {
        read_pool_size: 3,
        ..crate::config::StorageConfig::default()
    };
    assert_eq!(
        StorageConfig::from(&app).read_pool_size,
        3,
        "From must carry the parsed read_pool_size through"
    );

    // A stray 0 must clamp to 1 so the read pool can never stop retaining
    // connections entirely (mirrors the writer_queue_size >= 1 guard).
    let zero = crate::config::StorageConfig {
        read_pool_size: 0,
        ..crate::config::StorageConfig::default()
    };
    assert_eq!(
        StorageConfig::from(&zero).read_pool_size,
        1,
        "a stray read_pool_size=0 must clamp to 1"
    );

    // End-to-end: the value reaches the live handle and caps retained
    // default-provider read connections.
    run_storage_async_test(async {
        let temp_dir = tempfile::tempdir().expect("tempdir");
        let db_path = temp_dir.path().join("wa_test_y76wt_rpool.db");
        let db_path_str = db_path.to_string_lossy().to_string();

        let cx = crate::cx::for_testing();
        let app = crate::config::StorageConfig {
            read_pool_size: 3,
            ..crate::config::StorageConfig::default()
        };
        let storage =
            StorageHandle::with_config_with_cx(&cx, &db_path_str, StorageConfig::from(&app))
                .await
                .unwrap();
        assert_eq!(
            storage.read_pool_capacity(),
            3,
            "parsed [storage] read_pool_size=3 must reach the handle's read-pool capacity (was: default)"
        );

        let mut loans = Vec::new();
        for _ in 0..5 {
            let mut loan = storage
                .backend_provider
                .lend_read_backend(&db_path_str)
                .expect("lend read backend");
            loan.mark_successful_use();
            loans.push(loan);
        }
        drop(loans);

        let retained = read_pool()
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .get(&db_path_str)
            .map_or(0, Vec::len);
        assert_eq!(
            retained, 3,
            "read_pool_size=3 must cap retained idle read connections"
        );

        let _ = read_pool()
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .remove(&db_path_str);
        storage.shutdown().await.unwrap();
    });
}

/// ft-xbnl0.2.3 Cx-first: `StorageHandle::new_with_cx` must
/// return typed `Error::Cancelled` with storage-open context
/// when given a pre-cancelled cx, without creating the DB file
/// or spawning the writer thread.
#[test]
fn storage_handle_new_with_precancelled_cx_fails_before_fs_work() {
    run_storage_async_test(async {
        let temp_dir = std::env::temp_dir();
        let db_path = temp_dir.join(format!(
            "wa_test_new_with_cx_cancelled_{}.db",
            std::process::id()
        ));
        let db_path_str = db_path.to_string_lossy().to_string();

        let cx = crate::cx::for_testing();
        cx.cancel_with(
            crate::outcome::CancelKind::User,
            Some("pre-cancel storage open"),
        );

        let result = StorageHandle::new_with_cx(&cx, &db_path_str).await;
        let err = match result {
            Err(err) => err,
            Ok(_) => std::panic::resume_unwind(Box::new(
                "new_with_cx should fail on pre-cancelled cx",
            )),
        };

        match err {
            crate::Error::Cancelled(detail) => assert!(
                detail.contains("storage open"),
                "typed cancellation must retain storage-open context: {detail}"
            ),
            other => panic!("storage open must return Error::Cancelled, not {other:?}"),
        }
        assert!(
            !db_path.exists(),
            "DB file should not be created when cx is pre-cancelled"
        );
    });
}

